"use client";

import { forwardRef, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties } from "react";
import { animate, useInView, useReducedMotion } from "motion/react";
import SegmentedControl from "@/registry/components/segmented-control/segmented-control";
import { motionTokens } from "@/lib/motion-tokens";
import { stats as exampleStats, type Stat } from "./stats-band-data";
import styles from "./stats-band.module.css";

export type { Stat } from "./stats-band-data";
export type StatsBandLayout = "plain" | "divided";

export interface StatsBandProps {
  /** Three or four stats read best. */
  stats?: Stat[];
  /** `plain` lets the numbers float; `divided` rules the band top and bottom and draws a line between stats. */
  layout?: StatsBandLayout;
  title?: string;
  description?: string;
  /** Seconds each number takes to count up. Defaults to 1.6. */
  duration?: number;
  /** Number formatting locale. Fixed by default so server and client agree. */
  locale?: string;
  className?: string;
}

type Bezier = [number, number, number, number];
const enter = [...motionTokens.ease.enter] as Bezier;

function useFormatter(decimals: number, locale: string) {
  return useMemo(() => new Intl.NumberFormat(locale, { minimumFractionDigits: decimals, maximumFractionDigits: decimals, numberingSystem: "latn" }), [decimals, locale]);
}

/**
 * One number that counts from zero to its value the first time the band is in view. The final value reserves the
 * width underneath, so the layout never moves while digits change.
 */
function CountUp({ stat, run, delay, duration, reduced, locale }: { stat: Stat; run: boolean; delay: number; duration: number; reduced: boolean; locale: string }) {
  const live = useRef<HTMLSpanElement>(null);
  const done = useRef(false);
  const format = useFormatter(stat.decimals ?? 0, locale);
  const final = format.format(stat.value);

  useLayoutEffect(() => {
    if (reduced || done.current || !live.current) return;
    live.current.textContent = format.format(0);
  }, [format, reduced]);

  useEffect(() => {
    const node = live.current;
    if (!node) return;
    if (reduced) { node.textContent = final; done.current = true; return; }
    if (!run || done.current) return;
    const controls = animate(0, stat.value, {
      duration,
      delay,
      ease: enter,
      onUpdate: latest => { node.textContent = format.format(latest); },
      onComplete: () => { node.textContent = final; done.current = true; },
    });
    return () => controls.stop();
  }, [run, reduced, stat.value, delay, duration, format, final]);

  return <span className={styles.value}>
    <span className={styles.srOnly}>{stat.prefix}{final}{stat.suffix}</span>
    <span className={styles.number} aria-hidden="true">
      {stat.prefix && <span className={styles.affix}>{stat.prefix}</span>}
      <span className={styles.digits}>
        <span className={styles.sizer}>{final}</span>
        <span ref={live} className={styles.live}>{final}</span>
      </span>
      {stat.suffix && <span className={styles.affix}>{stat.suffix}</span>}
    </span>
  </span>;
}

/**
 * A band of three or four headline numbers that count up once as the band scrolls into view, in a plain or a
 * divided layout. Numbers use tabular figures and reserve their final width, and screen readers get the final value.
 */
export const StatsBand = forwardRef<HTMLElement, StatsBandProps>(function StatsBand({
  stats = exampleStats,
  layout = "plain",
  title,
  description,
  duration = 1.6,
  locale = "en-US",
  className,
}, ref) {
  const id = useId();
  const list = useRef<HTMLDListElement>(null);
  const inView = useInView(list, { once: true, amount: .5 });
  const reduced = !!useReducedMotion();
  return <section ref={ref} className={[styles.band, className].filter(Boolean).join(" ")} data-layout={layout} data-in-view={inView || reduced ? "" : undefined} aria-labelledby={title ? `${id}-title` : undefined} aria-label={title ? undefined : "Key numbers"}>
    <div className={styles.inner}>
      {(title || description) && <header className={styles.header}>
        {title && <h2 id={`${id}-title`} className={styles.title}>{title}</h2>}
        {description && <p className={styles.description}>{description}</p>}
      </header>}
      <dl ref={list} className={styles.stats} style={{ "--count": stats.length } as CSSProperties}>
        {stats.map((stat, index) => <div key={`${stat.label}-${index}`} className={styles.stat} style={{ "--i": index } as CSSProperties}>
          <dt className={styles.label}>{stat.label}</dt>
          <dd className={styles.figure}>
            <CountUp stat={stat} run={inView} delay={index * .09} duration={duration} reduced={reduced} locale={locale} />
          </dd>
          {stat.detail && <dd className={styles.detail}>{stat.detail}</dd>}
        </div>)}
      </dl>
    </div>
  </section>;
});

StatsBand.displayName = "StatsBand";

const layoutOptions = [{ value: "plain", label: "Plain" }, { value: "divided", label: "Divided" }];

/** Preview: the band in either layout. Switching layouts counts the numbers up again. */
export function StatsBandBlock() {
  const [layout, setLayout] = useState<StatsBandLayout>("divided");
  return <div className={styles.preview}>
    <SegmentedControl label="Stats layout" options={layoutOptions} value={layout} onValueChange={next => setLayout(next as StatsBandLayout)} />
    <div className={styles.frame}>
      <StatsBand key={layout} layout={layout} title="Trusted by teams who ship" description="Real numbers from the last twelve months." />
    </div>
  </div>;
}

export default StatsBandBlock;

export interface Stat {
  /** The final number. The band counts up to it. */
  value: number;
  /** Text before the number, such as "$". */
  prefix?: string;
  /** Text after the number, such as "%", "ms", or "+". */
  suffix?: string;
  /** Digits after the decimal point. Defaults to 0. */
  decimals?: number;
  label: string;
  /** One short supporting line under the label. */
  detail?: string;
}

export const stats: Stat[] = [
  { value: 12400, suffix: "+", label: "Teams shipping every week", detail: "From two person studios to public companies" },
  { value: 99.99, decimals: 2, suffix: "%", label: "Uptime over the last year", detail: "Across every region we run in" },
  { value: 38, suffix: "ms", label: "Median response time", detail: "Measured at the edge, worldwide" },
  { value: 4.9, decimals: 1, suffix: "/5", label: "Average rating", detail: "From 2,100 verified reviews" },
];

.band { container: stats / inline-size; background: var(--background); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
.band *, .band *::before, .band *::after { box-sizing: border-box; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.inner { max-width: 1120px; margin: 0 auto; padding: var(--space-16) var(--space-8); }
.header { display: grid; max-width: 36rem; gap: var(--space-3); margin-bottom: var(--space-10); }
.title { margin: 0; font-family: var(--font-display); font-size: clamp(1.75rem, 1rem + 3cqi, var(--text-4xl)); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); text-wrap: balance; }
.description { margin: 0; color: var(--text-secondary); font-size: var(--text-base); line-height: 1.5; text-wrap: pretty; }

.stats { position: relative; display: grid; grid-template-columns: repeat(var(--count), minmax(0, 1fr)); gap: var(--space-8); margin: 0; }
.stat { position: relative; display: flex; min-width: 0; flex-direction: column; }
.figure { order: -1; margin: 0 0 var(--space-3); }
.label { color: var(--foreground); font-size: var(--text-sm); font-weight: 500; line-height: var(--leading-body); }
.detail { margin: 2px 0 0; color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); text-wrap: pretty; }

.value { display: block; }
.number { display: inline-flex; align-items: baseline; font-family: var(--font-display); font-size: clamp(2.25rem, 1.2rem + 3.6cqi, var(--text-5xl)); font-weight: 500; letter-spacing: var(--tracking-display); line-height: 1; font-variant-numeric: tabular-nums; white-space: nowrap; }
.affix { color: var(--text-muted); font-size: .56em; letter-spacing: -.01em; }
.affix:first-child { margin-right: .06em; }
.affix:last-child { margin-left: .06em; }
.digits { display: inline-grid; justify-items: start; }
.sizer, .live { grid-area: 1 / 1; }
.sizer { visibility: hidden; }

/* Plain: stats rise gently into place as the band arrives. */
.stat { opacity: 0; transform: translateY(10px); transition: opacity 480ms var(--ease-enter), transform 640ms var(--ease-enter); transition-delay: calc(var(--i) * 90ms); }
.band[data-in-view] .stat { opacity: 1; transform: none; }

/* Divided: rules draw across the band, then a hairline grows between stats. */
.band[data-layout="divided"] .stats { gap: 0; padding: var(--space-8) 0; }
.band[data-layout="divided"] .stats::before,
.band[data-layout="divided"] .stats::after { content: ""; position: absolute; right: 0; left: 0; height: 1px; background: var(--border); transform: scaleX(0); transform-origin: left; transition: transform 900ms var(--ease-in-out); }
.band[data-layout="divided"] .stats::before { top: 0; }
.band[data-layout="divided"] .stats::after { bottom: 0; transition-delay: 120ms; }
.band[data-layout="divided"][data-in-view] .stats::before,
.band[data-layout="divided"][data-in-view] .stats::after { transform: scaleX(1); }
.band[data-layout="divided"] .stat { padding: var(--space-2) var(--space-8); }
.band[data-layout="divided"] .stat:first-child { padding-left: 0; }
.band[data-layout="divided"] .stat:not(:first-child)::before { content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 1px; background: var(--border); transform: scaleY(0); transform-origin: top; transition: transform 700ms var(--ease-enter); transition-delay: calc(var(--i) * 90ms + 240ms); }
.band[data-layout="divided"][data-in-view] .stat::before { transform: scaleY(1); }

@container stats (max-width: 760px) {
  .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: var(--space-10); }
  .band[data-layout="divided"] .stats { row-gap: 0; }
  .band[data-layout="divided"] .stat { padding: var(--space-6) var(--space-6); }
  .band[data-layout="divided"] .stat:nth-child(2n + 1) { padding-left: 0; }
  .band[data-layout="divided"] .stat:nth-child(2n + 1)::before { display: none; }
  .band[data-layout="divided"] .stat:nth-child(n + 3) { border-top: 1px solid var(--border); }
}
@container stats (max-width: 420px) {
  .inner { padding: var(--space-12) var(--space-4); }
  .stats { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-8); }
  .band[data-layout="divided"] .stat { padding: var(--space-6) 0; }
  .band[data-layout="divided"] .stat::before { display: none; }
  .band[data-layout="divided"] .stat:nth-child(n + 2) { border-top: 1px solid var(--border); }
}

.preview { display: grid; width: 100%; justify-items: center; gap: var(--space-4); }
.frame { width: 100%; overflow: hidden; border: 1px solid var(--border); border-radius: 20px; background: var(--background); }

@media (prefers-reduced-motion: reduce) {
  .stat, .band[data-layout="divided"] .stats::before, .band[data-layout="divided"] .stats::after, .band[data-layout="divided"] .stat::before { transition: none; }
  .stat { transform: none; }
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef } from "react";
import { LayoutGroup, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "@/lib/motion-tokens";
import styles from "./segmented-control.module.css";

export interface Segment { value: string; label: string; }
export interface SegmentedControlProps { options: Segment[]; value: string; onValueChange: (value: string) => void; label?: string; }

export default function SegmentedControl({ options, value, onValueChange, label }: SegmentedControlProps) {
  const id = useId();
  const reduced = useReducedMotion();
  const track = useRef<HTMLDivElement>(null);

  // When the options are wider than the container, the track scrolls inside itself. Edges fade only on the side with more to see.
  useLayoutEffect(() => {
    const node = track.current;
    if (!node) return;
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft;
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1);
      node.toggleAttribute("data-fade-end", rest > 1);
    };
    edges();
    node.addEventListener("scroll", edges, { passive: true });
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges);
    observer?.observe(node);
    return () => { node.removeEventListener("scroll", edges); observer?.disconnect(); };
  }, [options.length]);

  // The selected option is always scrolled fully into view, with a little room so it clears the fade.
  const first = useRef(true);
  useEffect(() => {
    const node = track.current;
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]');
    if (!node || !button || node.scrollWidth <= node.clientWidth) { first.current = false; return; }
    const room = 20, start = button.offsetLeft - room, end = button.offsetLeft + button.offsetWidth + room - node.clientWidth;
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft;
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" });
    first.current = false;
  }, [value, reduced]);

  return <div className={styles.root} role="group" aria-label={label}>
    <LayoutGroup id={id}><motion.div ref={track} layoutScroll className={styles.track}>
      {options.map(option => <button key={option.value} id={`${id}-${option.value}`} className={styles.button} type="button" aria-pressed={value === option.value} onClick={() => onValueChange(option.value)}>
        {value === option.value && <motion.span className={styles.selection} layoutId="selection" layoutDependency={value} transition={reduced ? { duration: 0 } : motionTokens.spring.morph} aria-hidden="true" />}
        <span className={styles.label}>{option.label}</span>
      </button>)}
    </motion.div></LayoutGroup>
  </div>;
}

/* The frame can shrink below its content inside flex and grid parents; the track then scrolls inside it. */
.root { display: inline-flex; min-width: 0; max-width: 100%; flex-shrink: 1; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-muted); }
/* The track owns the stacking context so the gliding highlight passes under every label, not over earlier ones. */
.track { --fade-start: 0px; --fade-end: 0px; isolation: isolate; display: flex; min-width: 0; gap: 2px; overflow-x: auto; overscroll-behavior-x: contain; padding: 3px; border-radius: inherit; scrollbar-width: none; -webkit-mask-image: linear-gradient(to right, transparent, #000 var(--fade-start), #000 calc(100% - var(--fade-end)), transparent); mask-image: linear-gradient(to right, transparent, #000 var(--fade-start), #000 calc(100% - var(--fade-end)), transparent); }
.track::-webkit-scrollbar { display: none; }
.track[data-fade-start] { --fade-start: 20px; }
.track[data-fade-end] { --fade-end: 20px; }
/* Items never scale or change weight; only the highlight travels and the label color follows it. */
.button { position: relative; flex: 0 0 auto; min-height: var(--control-height-sm); border: 0; border-radius: calc(var(--radius-control) - 3px); padding: 0 13px; background: transparent; color: var(--text-muted); font: inherit; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .button:hover { color: var(--foreground); } }
.button:active, .button[aria-pressed="true"] { color: var(--foreground); }
.selection { position: absolute; z-index: -1; inset: 0; border: 1px solid var(--border); border-radius: inherit; background: var(--surface); box-shadow: var(--shadow-resting); }
.label { position: relative; z-index: 1; }
@media (max-width: 380px) { .button { padding: 0 10px; } }
@media (prefers-reduced-motion: reduce) { .button { transition: none; } }
